struct probe{size_t aborts;struct t_loom_service_ref last_abort;int64_t register_rc;struct t_loom_service_ref register_id;size_t registrations;int64_t rc,destroy_rc;size_t returns,pool_retires[64],destroyed[64],retires,closes,freed;int retired;};
struct backing{unsigned char bytes[1024];struct probe *p;struct t_ring_core *core;};
static size_t count(void *b){(void)b;return 1;}static size_t length(void *b,size_t i){(void)b;(void)i;return 1024;}static const unsigned char *buffer(void *b,size_t i){(void)i;return ((struct backing *)b)->bytes;}
static int64_t ret(void *v,struct t_loom_service_buffer_receipt r){(void)r;struct probe *p=((struct backing *)v)->p;++p->returns;return p->rc;}
static void pool_retire(void *v,struct t_loom_service_ref r){++((struct backing *)v)->p->pool_retires[r.slot];}
static int64_t pool_destroy(void *v,struct t_loom_service_ref r){struct probe *p=((struct backing *)v)->p;if(!p->destroy_rc)++p->destroyed[r.slot];return p->destroy_rc;}
static void abort_scope(void *v,struct t_loom_service_ref scope){struct probe *p=((struct backing *)v)->p;++p->aborts;p->last_abort=scope;}
static void retire(void *v){++((struct backing *)v)->p->retires;}static int retired(void *v){return ((struct backing *)v)->p->retired;}static void close_owner(void *v){++((struct backing *)v)->p->closes;}static void destroy(void *v){struct backing *b=v;assert(b->p->closes==1);++b->p->freed;free(b);}
/* Pool headers plus bank cells the core holds: a pool is claimed before the
 * backend registers it, so nothing is claimed after the registration. */
static size_t claimed(const struct t_ring_core *c){size_t n=0;for(size_t i=0;i<64;++i)n+=c->pool_cells[i].used+!!c->bank.cells[i].owner;return n;}
static size_t at_register;
static struct t_ring_core *cores[256];static size_t ncores;
static void cores_idle(void){for(size_t i=0;i<ncores;++i){assert(t_ring_idle(cores[i]));free(cores[i]);}ncores=0;}
static int64_t register_pool(void *v,const struct t_loom_service_pool_member *ranges,size_t n,struct t_loom_service_ref *out){
 struct probe *p=((struct backing *)v)->p;assert(n&&ranges[0].length);++p->registrations;*out=p->register_id;at_register=claimed(((struct backing *)v)->core);return p->register_rc;
}
static void fixture(struct probe *p,struct t_ring_owner **r,struct t_ring_client **c){struct backing *b=calloc(1,sizeof(*b));assert(b);b->p=p;for(unsigned i=0;i<128;++i)memset(b->bytes+8*i,i,8);struct t_ring_core *core=calloc(1,sizeof(*core));assert(core&&ncores<256);cores[ncores++]=core;b->core=core;struct t_ring_backend backend={b,count,length,buffer,ret,pool_retire,pool_destroy,retire,retired,close_owner,destroy,register_pool,abort_scope};assert(!t_ring_create(backend,core,r,c));}
static struct t_loom_service_ref id(unsigned slot,uint64_t gen){return (struct t_loom_service_ref){slot,0,gen};}
static struct t_loom_service_pool_member range(uint64_t offset){return (struct t_loom_service_pool_member){0,0,offset,8};}
static struct t_loom_service_buffer_receipt receipt(unsigned slot,uint64_t gen,unsigned member,uint64_t lease){return (struct t_loom_service_buffer_receipt){.pool={slot,0,gen},.member=member,.lease=lease};}
static struct t_ring_pool *attach(struct t_ring_client *c,unsigned slot,uint64_t offset){struct t_ring_pool *p;struct t_loom_service_pool_member m=range(offset);assert(!t_ring_attach(c,id(slot,1),&m,1,&p));return p;}
static struct t_ring_payload *accept(struct t_ring_pool *p,unsigned slot){struct t_ring_payload *l;assert(t_ring_accept(p,8,4,receipt(slot,1,0,1),&l)==1);return l;}
static void view(struct t_ring_payload *l,unsigned char byte){size_t n=0;const unsigned char *p=t_ring_bytes(l,&n);assert(n==8);for(size_t i=0;i<n;++i)assert(p[i]==byte);}
static int64_t register_checked(struct t_ring_client *c,const struct t_loom_service_pool_member *m,size_t n,struct t_ring_pool **out,int64_t *rc){
 struct t_ring_core *core=c->core;size_t before=claimed(core);at_register=SIZE_MAX;int64_t result=t_ring_register_pool(c,m,n,out,rc);
 if(at_register==SIZE_MAX)assert(!*rc&&claimed(core)==before);else assert(at_register==before+1+n&&claimed(core)==(result==0||result==T_RING_UNCERTAIN?at_register:before));return result;
}
